+void dx_cp_async_graph_fp32_tile(
+        float* destination,
+        const float* source,
+        int source_index) {
+    constexpr int shared_ld = 40;
+    constexpr int global_ld = 512;
+    const int row = threadIdx.x >> 3;
+    const int col = (threadIdx.x & 7) * 4;
+    #pragma unroll
+    for (int load = 0; load < 2; ++load) {
+        const int current_row = row + load * 16;
+        const int shared_index = current_row * shared_ld + col;
+        unsigned destination_shared = static_cast<unsigned>(
